import numpy as np


def r(x):
    # Input transform: quadratic reduction of the step size/parameter
    return float(x**2)


def R(y_orig, y_new):
    # For program(x) = 6 + 3x, the deviation from the limit 6.0 is E(x) = 3x.
    # Under the quadratic input transform r(x) = x^2, the new deviation is E(x^2) = 3x^2.
    # This yields the second-order error relation: E(x^2) = E(x)^2 / 3.
    err_orig = y_orig - 6.0
    err_new = y_new - 6.0
    return np.isclose(err_new, (err_orig**2) / 3.0, atol=1e-12, rtol=1e-12)
